// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: montserratFamily } = loadMontserrat();



export type VelvetDiamondCardProps = Record<string, any>;

const VelvetDiamondCard: React.FC<VelvetDiamondCardProps> = ({
  backgroundColor = "#0a0a0c",
  transparentBackground = false,
  durationInSeconds = 5,
  skateImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/d50280b72baa4bec98e3b89f39668d15.png",
  mainTitle = "VELVET DIAMOND SETUP",
  subheading = "Built for rhythm. Made to stand out.",
  specLabels = [
    "Diamond G8 Boot",
    "Full Grain Leather + Suede Accents",
    "Sure-Grip Avanti Magnesium Plate",
    "Sure-Grip Velvet Wheels",
    "Qube Gold Bearings",
    "Fomac Dance Plug",
  ],
  accentColor = "#d4af37",
  textColor = "#f8f8f5",
  glowColor = "#d4af37",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle background transparency parsing safety
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Global Push-in Scale
  const globalScale = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [1, 1.05],
    { extrapolateRight: "clamp" }
  );

  // Title Animations
  const titleSpring = spring({
    frame: frame - 20,
    fps,
    config: { damping: 14 },
  });
  const titleOpacity = interpolate(frame, [20, 35], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const titleY = interpolate(titleSpring, [0, 1], [25, 0]);

  const subSpring = spring({
    frame: frame - 30,
    fps,
    config: { damping: 14 },
  });
  const subOpacity = interpolate(frame, [30, 45], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const subY = interpolate(subSpring, [0, 1], [25, 0]);

  // Skate Animations
  const skateSpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  const skateScale = interpolate(skateSpring, [0, 1], [0.85, 1]);
  const skateOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });
  const floatY = Math.sin(frame / 20) * 10;

  // Highlight Sweep Effect
  const sweepX = interpolate(frame, [110, 145], [-width, width], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Layout Spec Coordinates relative to canvas center
  const specsCoordinates = [
    { aX: -100, aY: -200, eX: -350, eY: -280, dX: -750, dY: -280 }, // Top Left
    { aX: -140, aY: 10, eX: -350, eY: -10, dX: -750, dY: -10 }, // Mid Left
    { aX: -100, aY: 220, eX: -350, eY: 260, dX: -750, dY: 260 }, // Bot Left
    { aX: 100, aY: -200, eX: 350, eY: -280, dX: 750, dY: -280 }, // Top Right
    { aX: 140, aY: 10, eX: 350, eY: -10, dX: 750, dY: -10 }, // Mid Right
    { aX: 100, aY: 220, eX: 350, eY: 260, dX: 750, dY: 260 }, // Bot Right
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* Background Radial Spotlight */}
      <svg width="100%" height="100%" style={{ position: "absolute" }}>
        <defs>
          <radialGradient id="bgSpotlight" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="rgba(255,255,255,0.06)" />
            <stop offset="100%" stopColor="transparent" />
          </radialGradient>
        </defs>
        <rect width="100%" height="100%" fill="url(#bgSpotlight)" />
      </svg>

      {/* Main Composition Wrapper for Parallax/Depth */}
      <AbsoluteFill
        style={{
          transform: `scale(${globalScale})`,
          transformOrigin: "center",
          transition: "none",
        }}
      >
        {/* Skate Hero Product */}
        <AbsoluteFill
          style={{ alignItems: "center", justifyContent: "center" }}
        >
          <Img
            src={skateImage}
            style={{
              width: 800,
              height: 800,
              objectFit: "contain",
              opacity: skateOpacity,
              transform: `scale(${skateScale}) translateY(${floatY}px)`,
              filter: `drop-shadow(0px 25px 45px rgba(0,0,0,0.7)) drop-shadow(0px 0px 30px ${glowColor}66)`,
              transition: "none",
            }}
          />
        </AbsoluteFill>

        {/* Header Text */}
        <AbsoluteFill
          style={{
            top: 80,
            alignItems: "center",
            height: 150,
            transition: "none",
          }}
        >
          <h1
            style={{
              fontFamily: playfairFamily,
              color: textColor,
              fontSize: 56,
              fontWeight: "bold",
              margin: 0,
              textTransform: "uppercase",
              letterSpacing: "8px",
              opacity: titleOpacity,
              transform: `translateY(${titleY}px)`,
              transition: "none",
            }}
          >
            {mainTitle}
          </h1>
          <h2
            style={{
              fontFamily: montserratFamily,
              color: textColor,
              fontSize: 22,
              fontWeight: 300,
              margin: "16px 0 0 0",
              letterSpacing: "4px",
              opacity: subOpacity,
              transform: `translateY(${subY}px)`,
              transition: "none",
            }}
          >
            {subheading}
          </h2>
        </AbsoluteFill>

        {/* Spec Callout Lines (SVG) */}
        <AbsoluteFill>
          <svg width={width} height={height} style={{ overflow: "visible" }}>
            {specLabels.slice(0, 6).map((label, i) => {
              const c = specsCoordinates[i];
              const startFrame = 50 + i * 12;
              const lineProgress = spring({
                frame: frame - startFrame,
                fps,
                config: { damping: 16, mass: 0.8 },
              });

              const path = `M ${width / 2 + c.aX} ${
                height / 2 + c.aY + floatY
              } L ${width / 2 + c.eX} ${height / 2 + c.eY} L ${
                width / 2 + c.dX
              } ${height / 2 + c.dY}`;

              const evolution = evolvePath(lineProgress, path);

              return (
                <g key={`line-${i}`}>
                  <path
                    d={path}
                    stroke={accentColor}
                    strokeWidth={2}
                    fill="none"
                    strokeDasharray={evolution.strokeDasharray}
                    strokeDashoffset={evolution.strokeDashoffset}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    opacity={0.8}
                  />
                  {/* Glowing Anchor Points */}
                  <circle
                    cx={width / 2 + c.aX}
                    cy={height / 2 + c.aY + floatY}
                    r={5}
                    fill={accentColor}
                    opacity={lineProgress}
                  />
                  <circle
                    cx={width / 2 + c.aX}
                    cy={height / 2 + c.aY + floatY}
                    r={12}
                    fill={accentColor}
                    opacity={lineProgress * 0.4}
                    filter="blur(4px)"
                  />
                </g>
              );
            })}
          </svg>

          {/* Spec Callout Text */}
          {specLabels.slice(0, 6).map((label, i) => {
            const c = specsCoordinates[i];
            const isLeft = i < 3;
            const startFrame = 50 + i * 12;

            const textSpring = spring({
              frame: frame - startFrame - 5,
              fps,
              config: { damping: 14 },
            });
            const textOpacity = interpolate(textSpring, [0, 1], [0, 1], {
              extrapolateRight: "clamp",
              extrapolateLeft: "clamp",
            });
            const textOffset = interpolate(
              textSpring,
              [0, 1],
              [isLeft ? 15 : -15, 0],
              { extrapolateRight: "clamp" }
            );

            const absEndY = height / 2 + c.dY;
            const absElbowX = width / 2 + c.eX;

            const containerStyle: React.CSSProperties = {
              position: "absolute",
              bottom: height - absEndY + 8,
              width: Math.abs(c.eX - c.dX),
              opacity: textOpacity,
              fontFamily: montserratFamily,
              color: textColor,
              fontSize: 18,
              fontWeight: 500,
              letterSpacing: "1px",
              textTransform: "uppercase",
              transform: `translateX(${textOffset}px)`,
              transition: "none",
            };

            if (isLeft) {
              containerStyle.right = width - absElbowX;
              containerStyle.textAlign = "right";
            } else {
              containerStyle.left = absElbowX;
              containerStyle.textAlign = "left";
            }

            return (
              <div key={`text-${i}`} style={containerStyle}>
                {label}
              </div>
            );
          })}
        </AbsoluteFill>
      </AbsoluteFill>

      {/* Volumetric Highlight Sweep */}
      <svg
        width={width}
        height={height}
        style={{
          position: "absolute",
          pointerEvents: "none",
          mixBlendMode: "overlay",
          overflow: "hidden",
          transition: "none",
        }}
      >
        <defs>
          <linearGradient id="sweepGrad" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="transparent" />
            <stop offset="40%" stopColor="transparent" />
            <stop offset="50%" stopColor="rgba(255, 255, 255, 0.4)" />
            <stop offset="60%" stopColor="transparent" />
            <stop offset="100%" stopColor="transparent" />
          </linearGradient>
        </defs>
        <g transform={`translate(${sweepX}, 0) skewX(-15)`}>
          <rect
            x={-width / 2}
            y={0}
            width={width * 1.5}
            height={height}
            fill="url(#sweepGrad)"
          />
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default VelvetDiamondCard;